import{_ as e,c as r,o,ag as n}from"./chunks/framework.CoPVQkzc.js";const b=JSON.parse('{"title":"Connector Reference","description":"All available source and destination connectors","frontmatter":{"title":"Connector Reference","description":"All available source and destination connectors"},"headers":[],"relativePath":"engine/connector_reference.md","filePath":"engine/connector_reference.md","lastUpdated":1788476353000}'),a={name:"engine/connector_reference.md"};function d(s,t,i,c,l,h){return o(),r("div",null,t[0]||(t[0]=[n('<h1 id="connector-reference" tabindex="-1">Connector Reference <a class="header-anchor" href="#connector-reference" aria-label="Permalink to &quot;Connector Reference&quot;">​</a></h1><p>Connectors are the protocol-specific endpoints that handle message I/O. Each connector type has both source (inbound) and/or destination (outbound) variants.</p><h2 id="tcp-mllp" tabindex="-1">TCP / MLLP <a class="header-anchor" href="#tcp-mllp" aria-label="Permalink to &quot;TCP / MLLP&quot;">​</a></h2><p><strong>Source:</strong> TCP Listener | <strong>Destination:</strong> TCP Sender</p><p>The most common connector for HL7 messaging over TCP using the MLLP (Minimum Lower Layer Protocol) framing.</p><h3 id="tcp-listener-source" tabindex="-1">TCP Listener (Source) <a class="header-anchor" href="#tcp-listener-source" aria-label="Permalink to &quot;TCP Listener (Source)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Host</strong></td><td>IP address to bind to (<code>0.0.0.0</code> for all interfaces)</td></tr><tr><td><strong>Port</strong></td><td>Listening port</td></tr><tr><td><strong>Transmission Mode</strong></td><td>MLLP or Basic mode</td></tr><tr><td><strong>Receive Timeout</strong></td><td>Milliseconds to wait for a complete message</td></tr><tr><td><strong>Max Connections</strong></td><td>Maximum concurrent connections</td></tr><tr><td><strong>Keep Connection Open</strong></td><td>Persist connections between messages</td></tr><tr><td><strong>Response</strong></td><td>ACK generation settings</td></tr></tbody></table><h3 id="tcp-sender-destination" tabindex="-1">TCP Sender (Destination) <a class="header-anchor" href="#tcp-sender-destination" aria-label="Permalink to &quot;TCP Sender (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Host</strong></td><td>Remote host address</td></tr><tr><td><strong>Port</strong></td><td>Remote port</td></tr><tr><td><strong>Transmission Mode</strong></td><td>MLLP or Basic mode</td></tr><tr><td><strong>Send Timeout</strong></td><td>Connection and send timeout</td></tr><tr><td><strong>Keep Connection Open</strong></td><td>Reuse connections</td></tr><tr><td><strong>Queue on Response Timeout</strong></td><td>Queue message if no response received</td></tr><tr><td><strong>Template</strong></td><td>Outgoing message content</td></tr></tbody></table><h3 id="transmission-modes" tabindex="-1">Transmission modes <a class="header-anchor" href="#transmission-modes" aria-label="Permalink to &quot;Transmission modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>MLLP</strong></td><td>Standard HL7 framing with start byte (<code>0x0B</code>), end bytes (<code>0x1C 0x0D</code>). Supports MLLPv2 with configurable ACK/NAK bytes.</td></tr><tr><td><strong>Basic</strong></td><td>Configurable start/end bytes</td></tr></tbody></table><h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><p><strong>Source:</strong> HTTP Listener | <strong>Destination:</strong> HTTP Sender</p><h3 id="http-listener-source" tabindex="-1">HTTP Listener (Source) <a class="header-anchor" href="#http-listener-source" aria-label="Permalink to &quot;HTTP Listener (Source)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Host</strong></td><td>Bind address</td></tr><tr><td><strong>Port</strong></td><td>Listening port</td></tr><tr><td><strong>Context Path</strong></td><td>URL path to listen on (e.g., <code>/api/messages</code>)</td></tr><tr><td><strong>Content Type</strong></td><td>Expected request content type</td></tr><tr><td><strong>Response Content Type</strong></td><td>Content type of the response</td></tr><tr><td><strong>HTTP Authentication</strong></td><td>None, Basic, Digest, JavaScript, Custom, OAuth 2.0 Token Verification</td></tr><tr><td><strong>Response Status Code</strong></td><td>HTTP status code to return</td></tr></tbody></table><h3 id="http-sender-destination" tabindex="-1">HTTP Sender (Destination) <a class="header-anchor" href="#http-sender-destination" aria-label="Permalink to &quot;HTTP Sender (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Target URL (supports variable substitution)</td></tr><tr><td><strong>Method</strong></td><td>GET, POST, PUT, DELETE, PATCH</td></tr><tr><td><strong>Headers</strong></td><td>Custom HTTP headers</td></tr><tr><td><strong>Parameters</strong></td><td>Query/form parameters</td></tr><tr><td><strong>Content Type</strong></td><td>Request body content type</td></tr><tr><td><strong>Authentication</strong></td><td>None, Basic, Digest</td></tr><tr><td><strong>Template</strong></td><td>Request body content</td></tr><tr><td><strong>Multipart</strong></td><td>Send as multipart/form-data</td></tr></tbody></table><h3 id="http-authentication-plugin-listener-only" tabindex="-1">HTTP Authentication Plugin (Listener only) <a class="header-anchor" href="#http-authentication-plugin-listener-only" aria-label="Permalink to &quot;HTTP Authentication Plugin (Listener only)&quot;">​</a></h3><p>Supports configurable authentication methods:</p><ul><li><strong>Basic</strong> - Username/password</li><li><strong>Digest</strong> - Digest authentication</li><li><strong>JavaScript</strong> - Custom authentication logic</li><li><strong>Custom</strong> - Custom Java class authentication</li><li><strong>OAuth 2.0 Token Verification</strong> - Validates incoming OAuth 2.0 tokens</li></ul><h2 id="file-ftp-sftp-s3-smb-webdav" tabindex="-1">File / FTP / SFTP / S3 / SMB / WebDAV <a class="header-anchor" href="#file-ftp-sftp-s3-smb-webdav" aria-label="Permalink to &quot;File / FTP / SFTP / S3 / SMB / WebDAV&quot;">​</a></h2><p><strong>Source:</strong> File Reader | <strong>Destination:</strong> File Writer</p><h3 id="file-reader-source" tabindex="-1">File Reader (Source) <a class="header-anchor" href="#file-reader-source" aria-label="Permalink to &quot;File Reader (Source)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Method</strong></td><td>File, FTP, SFTP, S3, SMB, WebDAV</td></tr><tr><td><strong>Directory</strong></td><td>Source directory path</td></tr><tr><td><strong>File Name Filter</strong></td><td>Filename pattern (wildcard or regex)</td></tr><tr><td><strong>Polling Frequency</strong></td><td>How often to check for new files</td></tr><tr><td><strong>Sort By</strong></td><td>Name, date, size</td></tr><tr><td><strong>After Processing</strong></td><td>Delete, move, or leave</td></tr><tr><td><strong>File Type</strong></td><td>Text or binary</td></tr><tr><td><strong>Encoding</strong></td><td>Character encoding</td></tr></tbody></table><h3 id="file-writer-destination" tabindex="-1">File Writer (Destination) <a class="header-anchor" href="#file-writer-destination" aria-label="Permalink to &quot;File Writer (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Method</strong></td><td>File, FTP, SFTP, S3, SMB, WebDAV</td></tr><tr><td><strong>Directory</strong></td><td>Target directory path</td></tr><tr><td><strong>File Name</strong></td><td>Output filename (supports variables)</td></tr><tr><td><strong>File Exists</strong></td><td>Overwrite, append, or error</td></tr><tr><td><strong>Encoding</strong></td><td>Character encoding</td></tr><tr><td><strong>Template</strong></td><td>File content</td></tr></tbody></table><h3 id="advanced-settings-per-protocol" tabindex="-1">Advanced settings (per protocol) <a class="header-anchor" href="#advanced-settings-per-protocol" aria-label="Permalink to &quot;Advanced settings (per protocol)&quot;">​</a></h3><ul><li><strong>FTP</strong> - Active/passive mode, timeout, secure mode (FTPS)</li><li><strong>SFTP</strong> - Key authentication, known hosts, algorithms</li><li><strong>S3</strong> - Bucket, region, access key, secret key</li><li><strong>SMB</strong> - Domain, credentials, SMB version</li></ul><h2 id="database-jdbc" tabindex="-1">Database (JDBC) <a class="header-anchor" href="#database-jdbc" aria-label="Permalink to &quot;Database (JDBC)&quot;">​</a></h2><p><strong>Source:</strong> Database Reader | <strong>Destination:</strong> Database Writer</p><h3 id="database-reader-source" tabindex="-1">Database Reader (Source) <a class="header-anchor" href="#database-reader-source" aria-label="Permalink to &quot;Database Reader (Source)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Driver</strong></td><td>MySQL, PostgreSQL, Oracle, SQL Server, or custom</td></tr><tr><td><strong>URL</strong></td><td>JDBC connection URL</td></tr><tr><td><strong>Username / Password</strong></td><td>Database credentials</td></tr><tr><td><strong>SQL</strong></td><td>SELECT query to poll for records</td></tr><tr><td><strong>Update</strong></td><td>Post-read UPDATE/DELETE statement</td></tr><tr><td><strong>Polling Frequency</strong></td><td>How often to execute the query</td></tr><tr><td><strong>Fetch Size</strong></td><td>Number of rows per fetch</td></tr></tbody></table><p>Each row returned by the query becomes an individual message.</p><h3 id="database-writer-destination" tabindex="-1">Database Writer (Destination) <a class="header-anchor" href="#database-writer-destination" aria-label="Permalink to &quot;Database Writer (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Driver</strong></td><td>Database driver</td></tr><tr><td><strong>URL</strong></td><td>JDBC connection URL</td></tr><tr><td><strong>Username / Password</strong></td><td>Database credentials</td></tr><tr><td><strong>SQL</strong></td><td>INSERT/UPDATE/DELETE statement</td></tr><tr><td><strong>Use JavaScript</strong></td><td>Use JavaScript instead of SQL for complex operations</td></tr></tbody></table><h3 id="supported-database-drivers" tabindex="-1">Supported database drivers <a class="header-anchor" href="#supported-database-drivers" aria-label="Permalink to &quot;Supported database drivers&quot;">​</a></h3><p>These are the drivers declared in <code>conf/dbdrivers.xml</code>, which is also where you add your own.</p><table tabindex="0"><thead><tr><th>Driver</th><th>Class</th><th>URL Template</th></tr></thead><tbody><tr><td>MySQL</td><td><code>com.mysql.cj.jdbc.Driver</code></td><td><code>jdbc:mysql://host:port/dbname</code></td></tr><tr><td>Oracle</td><td><code>oracle.jdbc.driver.OracleDriver</code></td><td><code>jdbc:oracle:thin:@host:port:dbname</code></td></tr><tr><td>PostgreSQL</td><td><code>org.postgresql.Driver</code></td><td><code>jdbc:postgresql://host:port/dbname</code></td></tr><tr><td>SQL Server/Sybase (jTDS)</td><td><code>net.sourceforge.jtds.jdbc.Driver</code></td><td><code>jdbc:jtds:sqlserver://host:port/dbname</code></td></tr><tr><td>Microsoft SQL Server</td><td><code>com.microsoft.sqlserver.jdbc.SQLServerDriver</code></td><td><code>jdbc:sqlserver://host:port;databaseName=dbname</code></td></tr><tr><td>SQLite</td><td><code>org.sqlite.JDBC</code></td><td><code>jdbc:sqlite:dbfile.db</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These are the databases a channel can <em>read from and write to</em>. They are not the same set OIE supports for its own message repository. See <a href="./database_support.html">Database Support</a> for that. SQLite, for instance, is available to channels but is not a supported backing store for OIE itself.</p></div><h2 id="channel-vm" tabindex="-1">Channel (VM) <a class="header-anchor" href="#channel-vm" aria-label="Permalink to &quot;Channel (VM)&quot;">​</a></h2><p><strong>Source:</strong> Channel Reader | <strong>Destination:</strong> Channel Writer</p><p>Internal connectors for passing messages between channels within the same OIE instance.</p><h3 id="channel-reader-source" tabindex="-1">Channel Reader (Source) <a class="header-anchor" href="#channel-reader-source" aria-label="Permalink to &quot;Channel Reader (Source)&quot;">​</a></h3><p>No configuration needed. The channel automatically receives messages sent to it by Channel Writers on other channels.</p><h3 id="channel-writer-destination" tabindex="-1">Channel Writer (Destination) <a class="header-anchor" href="#channel-writer-destination" aria-label="Permalink to &quot;Channel Writer (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Channel</strong></td><td>Target channel name or ID</td></tr><tr><td><strong>Template</strong></td><td>Message content to send</td></tr><tr><td><strong>Map Variables</strong></td><td>Pass channel map variables to the target</td></tr></tbody></table><p>This is the primary mechanism for multi-channel workflows and message routing chains.</p><h2 id="web-service-soap" tabindex="-1">Web Service (SOAP) <a class="header-anchor" href="#web-service-soap" aria-label="Permalink to &quot;Web Service (SOAP)&quot;">​</a></h2><p><strong>Source:</strong> Web Service Listener | <strong>Destination:</strong> Web Service Sender</p><h3 id="web-service-listener-source" tabindex="-1">Web Service Listener (Source) <a class="header-anchor" href="#web-service-listener-source" aria-label="Permalink to &quot;Web Service Listener (Source)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Class Name</strong></td><td>Service class name</td></tr><tr><td><strong>Service Name</strong></td><td>WSDL service name</td></tr><tr><td><strong>Port / Host</strong></td><td>Listening endpoint</td></tr></tbody></table><p>Auto-generates a WSDL endpoint.</p><h3 id="web-service-sender-destination" tabindex="-1">Web Service Sender (Destination) <a class="header-anchor" href="#web-service-sender-destination" aria-label="Permalink to &quot;Web Service Sender (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>WSDL URL</strong></td><td>URL of the WSDL definition</td></tr><tr><td><strong>Service / Port</strong></td><td>WSDL service and port to invoke</td></tr><tr><td><strong>Operation</strong></td><td>SOAP operation to call</td></tr><tr><td><strong>SOAP Envelope</strong></td><td>Full SOAP XML envelope template</td></tr><tr><td><strong>Authentication</strong></td><td>HTTP Basic</td></tr></tbody></table><h2 id="jms-java-message-service" tabindex="-1">JMS (Java Message Service) <a class="header-anchor" href="#jms-java-message-service" aria-label="Permalink to &quot;JMS (Java Message Service)&quot;">​</a></h2><p><strong>Source:</strong> JMS Listener | <strong>Destination:</strong> JMS Sender</p><h3 id="common-settings" tabindex="-1">Common settings <a class="header-anchor" href="#common-settings" aria-label="Permalink to &quot;Common settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Connection Factory</strong></td><td>JNDI connection factory class</td></tr><tr><td><strong>Destination</strong></td><td>Queue or topic name</td></tr><tr><td><strong>Username / Password</strong></td><td>JMS credentials</td></tr><tr><td><strong>JNDI Properties</strong></td><td>Initial context factory and provider URL</td></tr><tr><td><strong>Durable</strong></td><td>Durable topic subscription (listener only)</td></tr></tbody></table><p>Supports JMS-compatible providers (ActiveMQ, RabbitMQ JMS, IBM MQ, etc.).</p><h2 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h2><p><strong>Source:</strong> JavaScript Reader | <strong>Destination:</strong> JavaScript Writer</p><p>Fully custom connectors using JavaScript.</p><h3 id="javascript-reader-source" tabindex="-1">JavaScript Reader (Source) <a class="header-anchor" href="#javascript-reader-source" aria-label="Permalink to &quot;JavaScript Reader (Source)&quot;">​</a></h3><p>Write a script that returns messages. Useful for:</p><ul><li>Custom polling logic</li><li>REST API consumption</li><li>Complex data retrieval workflows</li></ul><h3 id="javascript-writer-destination" tabindex="-1">JavaScript Writer (Destination) <a class="header-anchor" href="#javascript-writer-destination" aria-label="Permalink to &quot;JavaScript Writer (Destination)&quot;">​</a></h3><p>Write a script that handles message delivery. Useful for:</p><ul><li>Custom protocol implementations</li><li>Multi-step delivery workflows</li><li>Complex business logic</li></ul><h2 id="smtp-email" tabindex="-1">SMTP (email) <a class="header-anchor" href="#smtp-email" aria-label="Permalink to &quot;SMTP (email)&quot;">​</a></h2><p><strong>Destination only:</strong> SMTP Sender</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>SMTP Host</strong></td><td>Mail server hostname</td></tr><tr><td><strong>SMTP Port</strong></td><td>Mail server port</td></tr><tr><td><strong>Encryption</strong></td><td>None, STARTTLS, SSL</td></tr><tr><td><strong>Username / Password</strong></td><td>SMTP authentication credentials</td></tr><tr><td><strong>From</strong></td><td>Sender email address</td></tr><tr><td><strong>To / CC / BCC</strong></td><td>Recipient addresses</td></tr><tr><td><strong>Subject</strong></td><td>Email subject</td></tr><tr><td><strong>Body</strong></td><td>Email body (HTML or plain text)</td></tr><tr><td><strong>Attachments</strong></td><td>File attachments</td></tr></tbody></table><h2 id="dicom" tabindex="-1">DICOM <a class="header-anchor" href="#dicom" aria-label="Permalink to &quot;DICOM&quot;">​</a></h2><p><strong>Source:</strong> DICOM Listener | <strong>Destination:</strong> DICOM Sender</p><p>For medical imaging workflows using the DICOM protocol.</p><h3 id="dicom-listener-source" tabindex="-1">DICOM Listener (Source) <a class="header-anchor" href="#dicom-listener-source" aria-label="Permalink to &quot;DICOM Listener (Source)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Host / Port</strong></td><td>Listening address</td></tr><tr><td><strong>AE Title</strong></td><td>Application Entity title</td></tr><tr><td><strong>TLS</strong></td><td>TLS encryption settings</td></tr></tbody></table><h3 id="dicom-sender-destination" tabindex="-1">DICOM Sender (Destination) <a class="header-anchor" href="#dicom-sender-destination" aria-label="Permalink to &quot;DICOM Sender (Destination)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Host / Port</strong></td><td>Remote PACS/modality address</td></tr><tr><td><strong>AE Title</strong></td><td>Local and remote AE titles</td></tr><tr><td><strong>Template</strong></td><td>DICOM data to send</td></tr></tbody></table><h2 id="document-writer" tabindex="-1">Document Writer <a class="header-anchor" href="#document-writer" aria-label="Permalink to &quot;Document Writer&quot;">​</a></h2><p><strong>Destination only:</strong> Document Writer</p><p>Generates PDF or RTF documents from message content.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Directory</strong></td><td>Output directory</td></tr><tr><td><strong>File Name</strong></td><td>Output file name</td></tr><tr><td><strong>Document Type</strong></td><td>PDF or RTF</td></tr><tr><td><strong>Template</strong></td><td>HTML template for document content</td></tr></tbody></table>',82)]))}const p=e(a,[["render",d]]);export{b as __pageData,p as default};
